import pytest


class InsufficientFunds(Exception):
    def __init__(self, needed):
        super().__init__(f"needs {needed} more")
        self.needed = needed


def withdraw(balances, name, amount):
    if amount <= 0:
        raise ValueError(f"amount must be positive, got {amount}")
    balance = balances[name]
    if amount > balance:
        raise InsufficientFunds(amount - balance)
    balances[name] = balance - amount


def test_rejects_zero_amount():
    with pytest.raises(ValueError, match="positive"):
        withdraw({"ann": 30}, "ann", 0)


def test_insufficient_funds():
    balances = {"ann": 30}

    with pytest.raises(InsufficientFunds) as info:
        withdraw(balances, "ann", 50)

    assert info.value.needed == 20
    assert balances == {"ann": 30}

